namespace RunnersZ.Logic { public static class Caesar { public static string Transform(string text,int shift,bool decrypt=false){if(shift<1||shift>25)throw new System.ArgumentOutOfRangeException(nameof(shift));int s=decrypt?-shift:shift;var r=new System.Text.StringBuilder();foreach(var c in text){if(c>='A'&&c<='Z')r.Append((char)('A'+(c-'A'+s+26)%26));else if(c>='a'&&c<='z')r.Append((char)('a'+(c-'a'+s+26)%26));else r.Append(c);}return r.ToString();}}}